-- SEED：节点-主题映射种子表
DROP TABLE IF EXISTS public.pm_map_node_subject_seed CASCADE;
CREATE TABLE public.pm_map_node_subject_seed (
  map_id                 text,
  project_no             text,
  subsystem              text,
  node_task              text,
  subproject_id          text,
  major_project_id       text,
  node_category          text,
  delay_reason_category  text,
  is_key_node            boolean,
  is_milestone           boolean,
  sort_order             int,
  source_flag            text,
  remark                 text
);

